import{_ as l,l as o,o as e,c as r,v as t,p as n,x as i,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"FLP 不可能","description":"","frontmatter":{"title":"FLP 不可能","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/flp-impossibility.md","filePath":"cs/flp-impossibility.md","lastUpdated":1789023840000}'),h={name:"cs/flp-impossibility.md"};function P(A,a,m,_,f,E){const s=o("Mermaid");return e(),r("div",null,[a[1]||(a[1]=t('<h1 id="flp-不可能" tabindex="-1">FLP 不可能 <a class="header-anchor" href="#flp-不可能" aria-label="Permalink to &quot;FLP 不可能&quot;">​</a></h1><div class="epigraph"><p>完全异步、确定性、哪怕只允许一个崩溃，共识没有既安全又活的算法。超时与随机是逃出去的洞，不是推翻。</p><footer>—— 据 Fischer, Lynch and Paterson, Impossibility of Distributed Consensus with One Faulty Process, JACM 1985 整理</footer></div><p>上一课<a href="/cs/leases">租约</a>靠期限才敢说「此刻只有一个主」。缺口是把这句话变成定理：<strong>没有时间界时，连「终将同意一个值」都不能保证</strong>。本课不重写崩溃停定义，不重做检测器分档。后课拜占庭是更强对手；FLP 在崩溃下已经足够否定。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>共识：终止（每个正确进程终决定）、一致（决定值相同）、有效（决定值是某输入）。模型：异步可靠信道、确定性进程、最多一个崩溃。Fischer–Lynch–Paterson：不存在满足三者的算法。</p><p>直觉：系统可以一直停在<strong>双价</strong>（bivalent）全局状态——两边决定都仍可能。从双价出发，调度器总能再走一步仍双价（否则那一步成了决定性步，对手推迟那条消息）。无限推迟则永不终止。证明的技术在于：单步改变一个进程的消息到达次序，用崩溃「藏起」那个进程。</p><p><span class="marginnote">Lynch 教材把 FLP 写成 I/O 自动机上的价论证。本课要的是模型边界：异步 + 确定 + 一崩溃 ⇒ 无共识。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>逃逸不推翻定理，只换模型：</p><ul><li>部分同步 / 检测器 \\(\\Diamond\\mathcal{S}\\)：活性依赖终将同步。</li><li>随机化（Ben-Or）：以概率 1 终止，期望轮数无界。</li><li>失败检测与超时：实现 \\(\\Diamond\\mathcal{P}\\) 的工程近似。</li><li>同步轮：直接有界。</li></ul>',10)),(e(),n(c,null,{default:i(()=>[d(s,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20ASYNC%5B%22%E5%BC%82%E6%AD%A5%E7%A1%AE%E5%AE%9A%20%2B%201%20%E5%B4%A9%E6%BA%83%22%5D%20--%3E%20IMP%5B%22FLP%3A%20%E6%97%A0%E5%85%B1%E8%AF%86%22%5D%0A%20%20PART%5B%22%E9%83%A8%E5%88%86%E5%90%8C%E6%AD%A5%22%5D%20--%3E%20OK%5B%22Paxos%20%2F%20Raft%20%E6%B4%BB%E6%80%A7%22%5D%0A%20%20RAND%5B%22%E9%9A%8F%E6%9C%BA%E5%8C%96%22%5D%20--%3E%20OK%0A%20%20SYNC%5B%22%E5%90%8C%E6%AD%A5%22%5D%20--%3E%20OK%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>Paxos 的安全在异步下成立，终止不保证——这不是实现偷懒，是 FLP 允许的形状。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>「双价」不是活锁 bug，是规格与模型的合取过强。工程上看到的选举超时、随机抖动，正是在部分同步里逼调度器离开双价区。把超时写进安全（「没在 30ms 内 ack 则另一值合法」）会破坏一致：那是用同步偷换异步。</p><p>信道不可靠（无限丢失）是另一条不可能，比 FLP 更粗：连投递都没有。FLP 假定可靠投递、只在调度上作恶，结论更锋利。</p><p>本课不把 CAP 当 FLP 的通俗版：CAP 谈分区与线性一致读写，FLP 谈异步崩溃与共识终止。后课会分开钉。也不把「区块链最终确认」当 FLP 反例：那些换了故障类、同步或概率。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写完整价引理，不引入拜占庭共识下界 \\(n\\gt 3f\\)。不把随机化协议的期望轮展开。后课默认：异步崩溃共识的安全与活要拆开证；看到「保证选出领导者」就问时间假设。下一课对手从崩溃升级到撒谎。</p><p>定理是模型的墙。后课所有多数派协议都在墙的某一侧开门。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>异步 + 确定 + 一崩溃 ⇒ 无既安全又终止的共识。</li><li>部分同步、随机、检测器是换模型，不是反例。</li><li>Paxos/Raft 安全异步、活性靠超时，形状符合 FLP。</li><li>出处：Fischer, Lynch and Paterson, JACM 1985。</li></ul>',10))])}const F=l(h,[["render",P]]);export{b as __pageData,F as default};
